# DOS U preset: Monkey Island 1 (mi1kor Korean patch), 2 bpp anti-aliased.
# M1U*.SVF baked by tools/korean/scumm-fonts/m1u.tsv: dialogue, verbs and the
# sentence line in a gothic face, the title/credit card in a serif face.
# Cells per charset: cs0 22x24, cs1/cs3 16x16, cs2 18x18, cs4 26x24.
# Charsets that share a cell share one SVF. Licences: see M12FONT.TXT beside this file.
[hires]
scale=2
alpha=true
missing=u+25a1

[font.0]
bitmap=M1U0.SVF

[font.1]
bitmap=M1U1.SVF

[font.2]
bitmap=M1U2.SVF

[font.3]
bitmap=M1U1.SVF

[font.4]
bitmap=M1U4.SVF

[latin]
mode=proportional
metrics=font
# No Latin companion here: font=same is a no-op today, and just says so -
# ASCII stays on each charset's own SVF, never the game's internal font.
font=same

# An ellipsis on the baseline, not a caret; present in every charset (mi1kor/hires_text.map,
# dumped from the 90x.LFL charsets: "...trailing off^" in the scanned patch text). Real
# punctuation, so it is drawn by the replacement font like any other character.
[glyphs]
0x5e = u+2026

# Solid arrows in the 2bpp dialogue and card charsets; 0x5f is a real underscore elsewhere.
[glyphs:cs2]
0x5f = keep
0x7f = keep

[glyphs:cs4]
0x5f = keep
0x7f = keep
